      "pinyin": "Dōng'ān Zǐjī",
      "provinceId": "prov-hunan",
      "cityVi": "Vĩnh Châu",
      "flavorProfile": "mala",
      "cookingOrFermentationTechVi": "Gà mái tơ non luộc chín tới rồi lọc xương cắt thanh nhỏ vừa ăn. Đầu bếp xào nhanh trên lửa lớn bằng dầu trà cùng gừng tươi thái sợi, ớt đỏ cay, hoa tiêu xanh và rượu gạo địa phương, sau đó chan giấm gạo trắng và nước luộc gà đun cạn nhanh tay cho thịt trắng mọng, chua cay thơm gừng.",
      "cookingOrFermentationTechEn": "A tender young pullet is gently poached, deboned, and cut into bite-sized strips. Stir-fried briskly in camellia oil with julienned fresh ginger, red chilies, green peppercorns, and local rice wine, it is splashed with white rice vinegar and chicken stock to yield pale, juicy meat with zesty sour-spicy notes.",
