      "pinyin": "Chángshā Chòudòufu",
      "provinceId": "prov-hunan",
      "cityVi": "Trường Sa",
      "flavorProfile": "mala",
      "cookingOrFermentationTechVi": "Đậu phụ ép chắc ngâm trong nước muối lên men tự nhiên ủ từ đậu tương đen, măng đông, nấm hương và rượu trắng nhiều tuần đến khi chuyển sắc xám đen. Đậu chiên phồng giòn rụm trong dầu trà sôi mà vẫn mềm béo bên trong, chọc lỗ giữa miếng rồi nhồi sốt tỏi ớt, rau mùi và củ cải muối cay.",
      "cookingOrFermentationTechEn": "Firm tofu squares are fermented for weeks in a natural brine of fermented black soybeans, winter bamboo shoots, shiitake, and liquor until charcoal-black. Deep-fried in camellia oil until blistered and crisp outside yet creamy inside, each piece is pierced and filled with garlicky chili broth, cilantro, and spicy pickled radish.",
      "gongfuBrewParams": null,
      "orderPhraseZh": "来一份现炸长沙臭豆腐，多浇蒜蓉辣汁和萝卜干。",
      "vietnamCulinaryEchoVi": "Hương lên men nồng nàn nhưng béo bùi khi ăn có nét đồng cảm văn hóa ẩm thực với mắm tôm chấm đậu phụ rán giòn trong bún đậu mắm tôm Hà Nội, cùng tôn vinh vị lên men thủ công.",
      "vietnamCulinaryEchoEn": "Its pungent fermentation paired with crispy fried tofu shares a cultural kinship with Hanoi's bun dau mam tom, where crisp tofu meets boldly fermented shrimp paste."
