      "provinceId": "prov-anhui",
      "cityVi": "Hoàng Sơn",
      "flavorProfile": "umami",
      "cookingOrFermentationTechVi": "Đậu phụ nước suối Hoàng Sơn cắt khối vuông và ủ trong phòng ẩm mát cùng bào tử nấm mốc có lợi Mucor đến khi bề mặt mọc lớp tơ trắng mịn như nhung. Đầu bếp áp chảo đậu bằng dầu hạt cải đến khi hai mặt vàng giòn, bên trong chuyển mềm dẻo béo ngậy như phô mai, chấm tương ớt tỏi.",
      "cookingOrFermentationTechEn": "Mountain-spring tofu cubes are inoculated with beneficial Mucor cultures and aged in cool humid rooms until blanketed in silky white mycelial fuzz. Pan-fried in rapeseed oil until golden-crisp outside and custardy like aged cheese inside, they are served hot with local garlicky chili paste.",
      "gongfuBrewParams": null,
