      "cookingOrFermentationTechEn": "Young Huangshan mountain pigeons are cleaned, blanched, and sealed in a porcelain tureen with cut Chinese yam, wild forest mushrooms, ginger slices, yellow wine, and clear spring water. Gently double-boiled for two hours, the clear broth stays crystal-clean while the pigeon turns tender and the yam remains creamy yet intact.",
