      "cookingOrFermentationTechVi": "Đặc sản đảo Quân Sơn giữa hồ Động Đình, từng búp trà phủ lông vàng trải qua diệt men rồi công đoạn ủ vàng gọi là muộn hoàng: gói trà trong giấy da bò giữ ẩm ấm nhiều giờ để diệp lục chuyển hóa dịu nhẹ. Kỹ thuật này bỏ vị ngái xanh, tạo nước vàng mơ và búp trà dựng đứng ba nhịp.",
      "cookingOrFermentationTechEn": "Harvested on Junshan Island in Lake Dongting, golden-downy buds undergo kill-green followed by menhuang (sealed yellowing): wrapped in paper under gentle warmth and humidity so chlorophyll mellows cleanly. This removes grassy sharpness, yielding bright apricot liquor where needles rise and fall vertically three times in glass.",
