      "vietnamCulinaryEchoVi": "Mông Sơn là một trong những cái nôi trồng trà cổ nhất lịch sử, gợi liên hệ với các vùng chè cổ thụ ngàn năm ở vùng núi Tây Bắc Việt Nam về cả sinh thái sương mù lẫn độ dịu ngọt của nước trà.",
